#!/usr/bin/env node
// Generated by OrchestKit Claude Plugin
// Created: 2026-10-08
// ============================================================================
// A skill that calls Workflow( must run inline, never as `context: fork`
// ============================================================================
// WHAT THIS GUARDS (#4672)
//
//   A `context: fork` skill runs in a forked agent that has the Agent tool but
//   NOT the Workflow tool (measured on CC 2.1.294 with claude -p). /ork:review-pr
//   ran 3 headless reviews as a single pass with 0 Agent and 0 Workflow calls
//   (runs de438e99, b91b1ab5, and 8a5bd5aa with a prompt-level fallback line,
//   which the fork ignored on cost grounds). Operator decision 2026-10-08: these
//   skills run inline, where the Workflow tool exists.
//
//   Fails if: any SKILL.md that calls `Workflow(` sets `context: fork`, or if
//   one of the five skills fixed here (review-pr, verify, assess, audit-full,
//   cover) stops calling Workflow( (the list below would then be stale), or if
//   no skill calls Workflow( at all (the scan would be broken).
// ============================================================================

import { existsSync, readdirSync, readFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.join(path.dirname(fileURLToPath(import.meta.url)), '..', '..', '..');
const SKILLS = path.join(ROOT, 'src', 'skills');
const FIXED = ['assess', 'audit-full', 'cover', 'review-pr', 'verify'];

const frontmatter = (text) => {
  const m = /^---\n([\s\S]*?)\n---\n/.exec(text);
  return m ? m[1] : '';
};

const failures = [];
const callers = [];
for (const name of readdirSync(SKILLS).sort()) {
  const file = path.join(SKILLS, name, 'SKILL.md');
  if (!existsSync(file)) continue;
  const text = readFileSync(file, 'utf8');
  if (!/\bWorkflow\(/.test(text)) continue;
  callers.push(name);
  if (/^context:\s*fork\s*$/m.test(frontmatter(text))) {
    failures.push(`src/skills/${name}/SKILL.md: calls Workflow( but sets context: fork (a fork has no Workflow tool, #4672)`);
  }
}

if (callers.length === 0) {
  console.log('FAIL: no skill calls Workflow(; the scan is broken');
  process.exit(1);
}
for (const name of FIXED) {
  if (!callers.includes(name)) failures.push(`src/skills/${name}/SKILL.md: no longer calls Workflow(; update FIXED in this test`);
}
for (const f of failures) console.log(`FAIL: ${f}`);
if (failures.length) process.exit(1);
console.log(`PASS: ${callers.length} skills call Workflow( and none sets context: fork`);
